contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint dep, uint am, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep);
        require(dep > 0);
        require(dep >= minSum);
        require(dep >= am);

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;

        uint beforeC = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeEther = address(this).balance;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterEther = address(this).balance;

        assert(reverted ? (afterC == beforeC && afterEther == beforeEther) : (afterC + am == beforeC && afterEther == beforeEther + am));
    }

    receive() external payable {}
}

