    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 dep, uint256 am, uint256 minSum) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        vm.assume(dep > 0);
        vm.assume(dep >= minSum);
        vm.assume(dep >= am);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 beforeC;
        try c.balances(address(this)) returns (uint256 __r) { beforeC = __r; } catch { return; }
        uint beforeEther = address(this).balance;
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterC;
        try c.balances(address(this)) returns (uint256 __r) { afterC = __r; } catch { return; }
        uint afterEther = address(this).balance;
        assertTrue(reverted ? (afterC == beforeC && afterEther == beforeEther) : (afterC + am == beforeC && afterEther == beforeEther + am));
    }

    function testFuzz_run(uint256 dep, uint256 am, uint256 minSum) public {
